<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { Library, UserRound, Map, Box, RefreshCw } from 'lucide-vue-next'
import { request } from '@/api'
import { tr } from '@/i18n'
import { useAuthStore } from '@/features/auth/authStore'
import AppTabs from '@/components/AppTabs.vue'
import AppSelect from '@/components/AppSelect.vue'
import { catalogApi } from '@/features/resource-library/catalog'
import { notice } from '@/shared/notice'
import type { Asset, Novel, PaginationResponse } from '@/types'
const auth=useAuthStore(),projects=ref<Novel[]>([]),project=ref(''),type=ref('character'),search=ref(''),keyword=ref(''),items=ref<Asset[]>([]),page=ref(1),pages=ref(1),loading=ref(false),error=ref('')
const editable=computed(()=>auth.enabled===false||['admin','creator','super'].includes(auth.role||''))
const projectOptions=computed(()=>projects.value.map(row=>({value:String(row.id),label:row.name})))
const tabs=computed(()=>[{value:'character',label:tr('角色'),icon:UserRound},{value:'scene',label:tr('场景'),icon:Map},{value:'prop',label:tr('道具'),icon:Box}])
let sequence=0,scope=0
async function load(next=1){const version=++sequence;page.value=next;items.value=[];if(!project.value)return;loading.value=true;error.value='';try{const params=new URLSearchParams({novel_id:project.value,asset_type:String({character:1,scene:2,prop:3}[type.value]||1),page:String(next),page_size:'24',search:keyword.value,sort:'canonical_name'});const result=await request<PaginationResponse<Asset>>(`/asset?${params}`);if(version===sequence){items.value=result.data.items;pages.value=result.data.pagination.pages}}catch(reason){if(version===sequence)error.value=reason instanceof Error?reason.message:tr('资产加载失败')}finally{if(version===sequence)loading.value=false}}
watch(()=>auth.activeTeamId,async()=>{const version=++scope;++sequence;project.value='';projects.value=[];items.value=[];loading.value=true;error.value='';try{const response=await catalogApi.projects();if(version!==scope)return;projects.value=response.data.items;project.value=String(projects.value[0]?.id||'')}catch(reason){if(version===scope)error.value=reason instanceof Error?reason.message:tr('项目加载失败')}finally{if(version===scope)loading.value=false}},{immediate:true})
watch([project,type],()=>{void load()})
async function publish(asset:Asset){const version=scope;try{await catalogApi.publish('asset',asset.id);if(version===scope)notice.success(tr('已存入团队资源库'))}catch(reason){if(version===scope)notice.error(reason instanceof Error?reason.message:tr('保存失败'))}}
onBeforeUnmount(()=>{++sequence;++scope})
</script>
<template><main class="assets-page"><header><div><h1>{{tr('项目资产')}}</h1><p>{{tr('管理每个项目独立的角色、场景和道具。')}}</p></div><RouterLink to="/resource-library"><Library :size="16"/>{{tr('前往资源库')}}</RouterLink></header><div class="asset-filters"><label>{{tr('项目')}}<AppSelect v-model="project" :options="projectOptions" :ariaLabel="tr('项目')" :disabled="!projects.length" /></label><form @submit.prevent="keyword=search.trim();load()"><input v-model="search" :placeholder="tr('搜索资产')" :aria-label="tr('搜索资产')"/><AppButton type="submit" size="sm">{{tr('搜索')}}</AppButton></form></div><AppTabs :items="tabs" :model-value="type" :label="tr('项目资产分类')" @update:model-value="type=$event"/><p class="asset-library-note">{{tr('公共角色和参考音色已统一在资源库管理。')}}</p><div v-if="loading" class="asset-state" role="status"><RefreshCw :size="23"/>{{tr('正在加载资产库…')}}</div><div v-else-if="error" class="asset-state" role="alert"><p>{{error}}</p><AppButton @click="load()">{{tr('重新加载')}}</AppButton></div><div v-else-if="items.length" class="project-asset-grid"><article v-for="asset in items" :key="asset.id" class="project-asset-card"><img v-if="asset.main_image" :src="asset.main_image_thumbnail||asset.main_image" :alt="asset.canonical_name" loading="lazy"/><div v-else class="asset-placeholder"><component :is="type==='character'?UserRound:type==='scene'?Map:Box" :size="30"/></div><div><h2>{{asset.canonical_name}}</h2><p>{{asset.description||tr('暂无资产描述')}}</p><AppButton v-if="editable" size="sm" variant="secondary" @click="publish(asset)">{{tr('存入团队资源库')}}</AppButton></div></article></div><div v-else class="asset-state"><Library :size="30"/><p>{{tr('暂无项目资产')}}</p></div><footer v-if="pages>1"><AppButton :disabled="page<=1||loading" @click="load(page-1)">{{tr('上一页')}}</AppButton><span>{{page}} / {{pages}}</span><AppButton :disabled="page>=pages||loading" @click="load(page+1)">{{tr('下一页')}}</AppButton></footer></main></template>
<style scoped>
.assets-page{padding:28px;background:var(--app-canvas);color:var(--app-text);min-height:100%}.assets-page>header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}h1{font-size:25px;margin:0 0 9px}header p{font-size:12px;color:var(--app-text-secondary);margin:0}header a{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--app-accent);text-decoration:none}.asset-filters{display:flex;gap:15px;justify-content:space-between;align-items:center;margin-bottom:20px;flex-wrap:wrap}.asset-filters label,.asset-filters form{display:flex;align-items:center;gap:10px;font-size:12px}input{min-width:0;max-width:100%;height:36px;padding:0 10px;border:1px solid var(--app-border);border-radius:7px;background:var(--app-surface);color:var(--app-text);font:inherit}.asset-filters .app-select{width:min(420px,50vw);min-width:200px;max-width:460px}.asset-library-note{font-size:11px;color:var(--app-text-secondary);margin:16px 0 22px}.project-asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}.project-asset-card{border:1px solid var(--app-border);border-radius:10px;background:var(--app-surface);overflow:hidden;min-width:0}.project-asset-card>img,.asset-placeholder{width:100%;height:180px;object-fit:cover;background:var(--app-surface-muted)}.asset-placeholder{display:grid;place-items:center;color:var(--app-text-secondary)}.project-asset-card>div:last-child{padding:15px}h2{font-size:14px;margin:0 0 10px}.project-asset-card p{font-size:11px;line-height:1.8;color:var(--app-text-secondary);display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}.asset-state{min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;color:var(--app-text-secondary);font-size:13px}footer{display:flex;justify-content:center;gap:12px;align-items:center;margin-top:25px}@media(max-width:640px){.assets-page{padding:18px 12px}.assets-page>header{flex-wrap:wrap}.asset-filters label{width:100%}.asset-filters .app-select{flex:1}.asset-filters form{width:100%}.asset-filters input{flex:1}.project-asset-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.project-asset-card>img,.asset-placeholder{height:130px}.project-asset-card>div:last-child{padding:10px}.project-asset-card h2{font-size:12px}}
</style>
